import { save } from "../../server/storage.ts";

const target = process.argv[2];
const payload = JSON.stringify({ users: Array.from({ length: 250_000 }, (_, i) => ({ id: "u" + i, name: "n".repeat(800) })) });
console.log("payload_bytes=" + Buffer.byteLength(payload));
for (let i = 0; i < 60; i++) {
  save(target, payload);
}
// Repro 3: error propagation of save(). Three probes:
// (a) target directory missing -> does save() throw or swallow?
// (b) overwrite of an existing good file when the write fails -> is backup preserved?
import { writeFileSync, readFileSync, existsSync } from "node:fs";
import { save } from "../../server/storage.ts";
const probe = process.argv[2];
if (probe === "missing-dir") {
  save("reports/repro/out/no/such/dir/x.json", "{}");
  console.log("NO THROW (unexpected)");
} else if (probe === "fsize") {
  // Existing valid content is replaced by a payload far above the RLIMIT_FSIZE
  // (set by caller shell), so the write must fail partway.
  writeFileSync("reports/repro/out/state.json", '{"users":[{"id":"seed","name":"seed"}]}');
  try {
    save("reports/repro/out/state.json", "x".repeat(10 * 1024 * 1024));
    console.log("SAVE_RETURNED_WITHOUT_THROW");
  } catch (e) {
    console.log("SAVE_THREW code=" + e.code + " message=" + e.message);
  }
  const after = readFileSync("reports/repro/out/state.json");
  console.log("size_after_failed_save=" + after.length + " equals_original=" + (after.toString() === '{"users":[{"id":"seed","name":"seed"}]}'));
}
// Repro 5: real ENOSPC mid-write on a mounted 2 MB APFS disk image.
// Seed a valid JSON file, then save() a 5 MB payload -> write fails partway.
import { writeFileSync, readFileSync } from "node:fs";
import { save } from "../../server/storage.ts";
const target = "/Volumes/TINYENOSPC/state.json";
const GOOD = JSON.stringify({ users: [{ id: "seed", name: "x".repeat(100_000) }] });
writeFileSync(target, GOOD);
console.log("seed_size=" + readFileSync(target).length);
try {
  save(target, "y".repeat(5 * 1024 * 1024));
  console.log("SAVE_RETURNED_WITHOUT_THROW");
} catch (e) {
  console.log("SAVE_THREW code=" + e.code);
}
const after = readFileSync(target);
console.log("size_after_failed_save=" + after.length + " equals_seed=false? " + (after.toString() !== GOOD) + " starts_with_y=" + (after[0] === 0x79));
// Repro 4: two processes call save() concurrently on the same file with distinct
// payloads of unequal size. Does the final content equal one complete payload?
import { spawn } from "node:child_process";
import { writeFileSync, readFileSync } from "node:fs";
import process from "node:process";
const target = "reports/repro/out/concurrent.json";
const make = (ch: string, len: number, tail: string) => ch.repeat(len) + tail;
const A = make("A", 8 * 1024 * 1024, "|END-A");
const B = make("B", 4 * 1024 * 1024, "|END-B");
writeFileSync(target, "seed");
const writerSrc = (ch: string, len: number, tail: string) =>
  `import { save } from "../../../server/storage.ts";\nimport process from "node:process";\nconst p = "${ch}".repeat(${len}) + "${tail}";\nfor (let i = 0; i < 60; i++) save(process.argv[2], p);\n`;
writeFileSync("reports/repro/out/wA.ts", writerSrc("A", 8 * 1024 * 1024, "|END-A"));
writeFileSync("reports/repro/out/wB.ts", writerSrc("B", 4 * 1024 * 1024, "|END-B"));
const kids = ["reports/repro/out/wA.ts", "reports/repro/out/wB.ts"].map(f =>
  spawn(process.execPath, [f, target], { stdio: "ignore" }));
await Promise.all(kids.map(k => new Promise(r => k.on("exit", r))));
const final = readFileSync(target, "utf8");
const isA = final === A, isB = final === B;
console.log("final_len=" + final.length + " is_exact_A=" + isA + " is_exact_B=" + isB);
if (!isA && !isB) {
  const counts: Record<string, number> = {};
  for (const ch of final) counts[ch] = (counts[ch] ?? 0) + 1;
  console.log("byte_histogram=" + JSON.stringify(counts) + " tail=" + JSON.stringify(final.slice(-10)));
  console.log("RESULT: FINAL CONTENT IS A MIX/TORN WRITE (neither writer's payload survived intact)");
}
